SELECT id, location, budget, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget, STDDEV_SAMP(budget) OVER (PARTITION BY location, dept_name) AS location_stddev_samp_budget, ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget DESC, id) AS seq_no, FIRST_VALUE(budget, TRUE) OVER (ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_budget, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget_2 FROM departments WHERE budget >= 3743000;
